package world.gregs.voidps.cache.type.data

import world.gregs.voidps.cache.CacheType

/**
 * A material record. [version] selects which of the two wire layouts it was written in, so a field
 * only holds a value when the layout that carries it also had its flag bit set.
 */
data class MaterialType(
    override var id: Int = -1,
    var version: Int = 0,
    var flags: Int = 0,
    var extraFlags: Int = 0,
    var textureSizeCode: Int = 0,
    var unknown1: Int = 0,
    var unknown2: Int = 0,
    var unknown3: Int = 0,
    var packed: Int = 0,
    var unknown4: Int = 0,
    var unknown5: Int = 0,
    var unknown6: Float = 0f,
    var unknown7: Float = 0f,
    var unknown8: Float = 0f,
    var unknown9: Float = 0f,
    var unknown10: Float = 0f,
    var unknown11: Float = 0f,
    var unknown12: Float = 0f,
    var unknown13: Int = 0,
    var unknown14: Int = 0,
    var unknown15: Int = 0,
    var unknown16: Int = 0,
    var unknown17: Float = 0f,
    var unknown18: Float = 0f,
    var unknown19: Float = 0f,
    var unknown20: Int = 0,
    var scrollU: Int = 0,
    var scrollV: Int = 0,
    var unknown21: Float = 0f,
    var unknown22: Int = 0,
    var unknown23: Int = 0,
    var unknown24: Int = 0,
    var unknown25: Int = 0,
    var unknown26: Int = 0,
    var unknown27: Int = 0,
    var unknown28: Int = 0,
    var unknown29: Int = 0,
    var unknown30: Int = 0,
    var unknown31: Int = 0,
    var unknown32: Int = 0,
    var colour: Int = 0,
    var unknown33: Int = 0,
    var unknown34: Int = 0,
    var unknown35: Int = 0,
    var unknown36: Int = 0,
    var unknown37: Int = 0,
    var unknown38: Int = 0,
    var unknown39: Float = 0f,
    var unknown40: Int = 0,
    var unknown41: Float = 0f,
    var unknown42: Float = 0f,
    var unknown43: Float = 0f,
    var unknown44: Float = 0f,
    var unknown45: Int = 0,
    var unknown46: Int = 0,
) : CacheType
